884	        /**
885	         Determines the request method for an automatic redirect, or null if the status is not automatically redirected.
886	         See <a href="https://www.rfc-editor.org/rfc/rfc9110.html#section-15.4">RFC 9110, Section 15.4</a>.
887	         */
888	        static @Nullable Method redirectMethod(int statusCode, Method method) {
889	            switch (statusCode) {
890	                case 301: // Moved Permanently
891	                case 302: // Found
892	                    return method == Method.POST ? Method.GET : method;
893	                case 303: // See Other
894	                    return method == Method.HEAD ? Method.HEAD : Method.GET;
895	                case 307: // Temporary Redirect
896	                case 308: // Permanent Redirect
897	                    return method;
898	                default:
899	                    return null;
900	            }
901	        }
