915	        static Response execute(HttpConnection.Request req, @Nullable Response prevRes) throws IOException {
916	            Validate.isTrue(req.executing.tryLock(), "Multiple threads were detected trying to execute the same request concurrently. Make sure to use Connection#newRequest() and do not share an executing request between threads.");
917	            Validate.notNullParam(req, "req");
918	            URL url = req.url();
919	            Validate.notNull(url, "URL must be specified to connect");
920	            String protocol = url.getProtocol();
921	            if (!protocol.equals("http") && !protocol.equals("https"))
922	                throw new MalformedURLException("Only http & https protocols supported");
923	            final boolean supportsBody = req.method().hasBody();
924	            final boolean hasBody = req.body != null;
925	            if (!supportsBody)
926	                Validate.isFalse(hasBody, "Cannot set a request body for HTTP method " + req.method());
927	
928	            // set up the request for execution
929	            if (!req.data().isEmpty() && (!supportsBody || hasBody))
930	                serialiseRequestUrl(req);
931	            else if (supportsBody)
932	                setOutputContentType(req);
933	
934	            long startTime = System.nanoTime();
935	            RequestExecutor executor = RequestDispatch.get(req, prevRes);
936	            Response res = null;
937	            try {
938	                res = executor.execute();
939	
940	                Method nextMethod = redirectMethod(res.statusCode, req.method());
941	                if (nextMethod != null && res.hasHeader(LOCATION) && req.followRedirects()) {
942	                    if (nextMethod == req.method() && (req.body instanceof InputStream || needsMultipart(req)))
943	                        throw new IOException("Cannot follow redirect with a streamed request body; disable followRedirects and resend with a fresh stream");
944	
945	                    if (nextMethod != req.method()) {
946	                        req.method(nextMethod);
947	                        req.data().clear();
948	                        req.requestBody(null);
949	                        for (String header : REDIRECT_CONTENT_HEADERS)
950	                            req.removeHeader(header);
951	                    }
952	
953	                    String location = res.header(LOCATION);
954	                    Validate.notNull(location);
955	                    URL redir = StringUtil.resolve(req.url(), location);
956	                    if (!sameOrigin(req.url(), redir)) {
957	                        // remove sensitive headers; defense-in-depth against open redirects
958	                        req.removeHeader("Authorization");
959	                        req.removeHeader("Cookie");
960	                        req.removeHeader("Cookie2");
961	                        req.cookies().clear();
962	                    }
963	                    req.url(redir);
964	
965	                    return execute(req, res);
966	                }
967	                if ((res.statusCode < 200 || res.statusCode >= 400) && !req.ignoreHttpErrors())
968	                        throw new HttpStatusException("HTTP error fetching URL", res.statusCode, req.url().toString());
969	
970	                // check that we can handle the returned content type; if not, abort before fetching it
971	                String contentType = res.contentType();
972	                boolean isText = contentType != null && contentType.regionMatches(true, 0, "text/", 0, 5);
973	                boolean isXml = contentType != null && xmlContentTypeRxp.matcher(contentType).matches();
974	
975	                if (contentType != null
976	                        && !req.ignoreContentType()
977	                        && !isText
978	                        && !isXml
979	                        )
980	                    throw new UnsupportedMimeTypeException("Unhandled content type. Must be a text or XML media type",
981	                            contentType, req.url().toString());
982	
983	                // switch to the XML parser if content type is xml and not parser not explicitly set
984	                if (isXml) {
985	                    if (!req.parserDefined) req.parser(Parser.xmlParser());
986	                }
987	
988	                res.charset = DataUtil.getCharsetFromContentType(res.contentType); // may be null, readInputStream deals with it
989	                if (res.contentLength != 0 && req.method() != HEAD) { // -1 means unknown, chunked. sun throws an IO exception on 500 response with no content when trying to read body
990	                    InputStream stream = executor.responseBody();
991	                    if (res.hasHeaderWithValue(CONTENT_ENCODING, "gzip"))
992	                        stream = new GZIPInputStream(stream);
993	                    else if (res.hasHeaderWithValue(CONTENT_ENCODING, "deflate"))
994	                        stream = new InflaterInputStream(stream, new Inflater(true));
995	                    
996	                    res.bodyStream = ControllableInputStream.wrap(
997	                        stream, DefaultBufferSize, req.maxBodySize())
998	                        .timeout(startTime, req.timeout());
999	
1000	                    if (req.responseProgress != null) // set response progress listener
1001	                        res.bodyStream.onProgress(res.contentLength, req.responseProgress, res);
1002	                } else {
1003	                    res.byteData = DataUtil.emptyByteBuffer();
1004	                }
1005	            } catch (IOException e) {
1006	                if (res != null) res.safeClose(); // will be non-null if got to conn
1007	                throw e;
1008	            } finally {
1009	                req.executing.unlock();
1010	
1011	                // detach any thread local auth delegate
1012	                if (req.authenticator != null)
1013	                    AuthenticationHandler.handler.remove();
1014	            }
1015	
1016	            res.executed = true;
1017	            return res;
1018	        }
