1231	        /**
1232	         Servers may encode response headers in UTF-8 instead of RFC defined 8859. The JVM decodes the headers (before we see them) as 8859, which can lead to mojibake data.
1233	         <p>This method attempts to detect that and re-decode the string as UTF-8.</p>
1234	         <p>However on Android, the headers will be decoded as UTF8, so we can detect and pass those directly.</p>
1235	         * @param val a header value string that may have been incorrectly decoded as 8859.
1236	         * @return a potentially re-decoded string.
1237	         */
1238	        @Nullable
1239	        static String fixHeaderEncoding(@Nullable String val) {
1240	            if (val == null) return val;
1241	            // If we can't encode the string as 8859, then it couldn't have been decoded as 8859
1242	            if (!StandardCharsets.ISO_8859_1.newEncoder().canEncode(val))
1243	                return val;
1244	            byte[] bytes = val.getBytes(ISO_8859_1);
1245	            if (looksLikeUtf8(bytes))
1246	                return new String(bytes, UTF_8);
1247	            else
1248	                return val;
1249	        }
