1251	        private static boolean looksLikeUtf8(byte[] input) {
1252	            int i = 0;
1253	            // BOM:
1254	            if (input.length >= 3
1255	                && (input[0] & 0xFF) == 0xEF
1256	                && (input[1] & 0xFF) == 0xBB
1257	                && (input[2] & 0xFF) == 0xBF) {
1258	                i = 3;
1259	            }
1260	
1261	            int end;
1262	            boolean foundNonAscii = false;
1263	            for (int j = input.length; i < j; ++i) {
1264	                int o = input[i];
1265	                if ((o & 0x80) == 0) {
1266	                    continue; // ASCII
1267	                }
1268	                foundNonAscii = true;
1269	
1270	                // UTF-8 leading:
1271	                if ((o & 0xE0) == 0xC0) {
1272	                    end = i + 1;
1273	                } else if ((o & 0xF0) == 0xE0) {
1274	                    end = i + 2;
1275	                } else if ((o & 0xF8) == 0xF0) {
1276	                    end = i + 3;
1277	                } else {
1278	                    return false;
1279	                }
1280	
1281	                if (end >= input.length)
1282	                    return false;
1283	
1284	                while (i < end) {
1285	                    i++;
1286	                    o = input[i];
1287	                    if ((o & 0xC0) != 0x80) {
1288	                        return false;
1289	                    }
1290	                }
1291	            }
1292	            return foundNonAscii;
1293	        }
