1325	        private static void implWritePost(final HttpConnection.Request req, final BufferedWriter w, final OutputStream outputStream) throws IOException {
1326	            final Collection<Connection.KeyVal> data = req.data();
1327	            final String boundary = req.mimeBoundary;
1328	
1329	            if (boundary != null) { // a multipart post
1330	                for (Connection.KeyVal keyVal : data) {
1331	                    w.write("--");
1332	                    w.write(boundary);
1333	                    w.write("\r\n");
1334	                    w.write("Content-Disposition: form-data; name=\"");
1335	                    w.write(encodeMimeName(keyVal.key())); // encodes " to %22
1336	                    w.write("\"");
1337	                    final InputStream input = keyVal.inputStream();
1338	                    if (input != null) {
1339	                        w.write("; filename=\"");
1340	                        w.write(encodeMimeName(keyVal.value()));
1341	                        w.write("\"\r\nContent-Type: ");
1342	                        String contentType = keyVal.contentType();
1343	                        if (contentType != null)
1344	                            validateMimeContentType(contentType);
1345	                        w.write(contentType != null ? contentType : DefaultUploadType);
1346	                        w.write("\r\n\r\n");
1347	                        w.flush();
1348	                        DataUtil.crossStreams(input, outputStream);
1349	                        outputStream.flush();
1350	                    } else {
1351	                        w.write("\r\n\r\n");
1352	                        w.write(keyVal.value());
1353	                    }
1354	                    w.write("\r\n");
1355	                }
1356	                w.write("--");
1357	                w.write(boundary);
1358	                w.write("--");
1359	            } else if (req.body != null) { // a single body (bytes or plain text);  data will be in query string
1360	                if (req.body instanceof String) {
1361	                    w.write((String) req.body);
1362	                } else if (req.body instanceof InputStream) {
1363	                    DataUtil.crossStreams((InputStream) req.body, outputStream);
1364	                    outputStream.flush();
1365	                } else {
1366	                    throw new IllegalStateException();
1367	                }
1368	            } else { // regular form data (application/x-www-form-urlencoded)
1369	                boolean first = true;
1370	                for (Connection.KeyVal keyVal : data) {
1371	                    if (!first) w.append('&');
1372	                    else first = false;
1373	
1374	                    w.write(URLEncoder.encode(keyVal.key(), req.postDataCharset()));
1375	                    w.write('=');
1376	                    w.write(URLEncoder.encode(keyVal.value(), req.postDataCharset()));
1377	                }
1378	            }
1379	        }
